import json,subprocess
from pathlib import Path
s=Path('/srv/projects/android-sdk'); o={}
for k,p in {'aapt2':'build-tools/36.0.0/aapt2','zipalign':'build-tools/36.0.0/zipalign','apksigner':'build-tools/36.0.0/lib/apksigner.jar','adb':'platform-tools/adb'}.items():
